struct Base {
    void (*print_total)(struct Base *self, int value);
};

struct Derived {
    struct Base base;
    // additional members
};

// Function implementations
void base_print_total(struct Base *self, int value);
void derived_print_total(struct Base *self, int value);

// Usage
struct Derived d;
// Assign function pointers at runtime

d.base.print_total = derived_print_total;

// Call via base pointer
struct Base *b = (struct Base *)&d;
b->print_total(b, 10);

code_example:
struct Base {
    void (*print_total)(struct Base *self, int value);
};
struct Derived {
    struct Base base;
    // additional members
};
void base_print_total(struct Base *self, int value) {
    printf("Base total: %d\n", value);
}
void derived_print_total(struct Base *self, int value) {
    printf("Derived total: %d\n", value);
}
// Instantiate derived object and assign function pointer

struct Derived d;

d.base.print_total = derived_print_total;
// Call method via base pointer, enabling dynamic dispatch

struct Base *b = (struct Base *)&d;

b->print_total(b, 10);
